// Robustness tests for FastPFOR stream decoding.
//
// The FastPFOR library the decoder is based on is documented as follows:
//
//   It is a low-level library. The inputs are not validated prior to decoding. It is assumed that the provided
//   buffers were generated by the corresponding encoding functions. It is your responsibility to ensure the
//   validity of your data.
//
// Tiles come from arbitrary sources, so the decoder must reject malformed streams instead. These tests feed it
// streams that lie about their lengths, counts and bit widths. Run them under ASan/UBSan to catch any access that
// is out of bounds but happens to not crash.

#include <gtest/gtest.h>

#include <mlt/decode/fastpfor.hpp>
#include <mlt/decode/int.hpp>
#include <mlt/decode/int_template.hpp> // NOLINT(misc-include-cleaner)
#include <mlt/metadata/stream.hpp>
#include <mlt/util/buffer_stream.hpp>

#include <fastpfor/compositecodec.h>
#include <fastpfor/fastpfor.h>
#include <fastpfor/variablebyte.h>

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <random>
#include <stdexcept>
#include <vector>

namespace {

using namespace mlt;
using namespace mlt::metadata::stream;

using Words = std::vector<std::uint32_t>;
using Codec = FastPForLib::CompositeCodec<FastPForLib::FastPFor<8>, FastPForLib::VariableByte>;

// Compress as the encoder does, returning the native-endian words
Words compress(const std::vector<std::uint32_t>& values) {
    Words compressed(2 * values.size() + 1024);
    std::size_t size = compressed.size();
    Codec{}.encodeArray(values.data(), values.size(), compressed.data(), size);
    compressed.resize(size);
    return compressed;
}

// Serialize words as they appear in a tile: big-endian
std::vector<char> toStream(const Words& words) {
    std::vector<char> bytes;
    bytes.reserve(words.size() * sizeof(std::uint32_t));
    for (const auto word : words) {
        for (int shift = 24; shift >= 0; shift -= 8) {
            bytes.push_back(static_cast<char>((word >> shift) & 0xff));
        }
    }
    return bytes;
}

std::vector<std::uint32_t> sequence(std::size_t count) {
    std::vector<std::uint32_t> values(count);
    std::mt19937 rng(42);
    for (auto& value : values) {
        // mostly small values, some outliers so that the stream contains exceptions
        value = (rng() % 16 == 0) ? rng() : rng() % 100;
    }
    return values;
}

StreamMetadata makeMetadata(std::size_t numValues, std::size_t byteLength) {
    return {PhysicalStreamType::DATA,
            std::nullopt,
            LogicalLevelTechnique::NONE,
            LogicalLevelTechnique::NONE,
            PhysicalLevelTechnique::FAST_PFOR,
            static_cast<std::uint32_t>(numValues),
            static_cast<std::uint32_t>(byteLength)};
}

// Decode the stream, which `data` must be exactly sized so that sanitizers detect reads past the end.
std::vector<std::uint32_t> decode(const std::vector<char>& data,
                                  std::size_t numValues,
                                  std::size_t byteLength,
                                  std::size_t leadingBytes = 0) {
    decoder::IntegerDecoder intDecoder;
    BufferStream stream({data.data() + leadingBytes, data.size() - leadingBytes});
    std::vector<std::uint32_t> result;
    intDecoder.decodeIntStream<std::uint32_t>(stream, result, makeMetadata(numValues, byteLength), false);
    return result;
}

std::vector<std::uint32_t> decode(const std::vector<char>& data, std::size_t numValues) {
    return decode(data, numValues, data.size());
}

} // namespace

TEST(FastPforDecode, ValidStream) {
    for (const std::size_t count : {1ul, 3ul, 255ul, 256ul, 257ul, 1000ul, 4096ul}) {
        const auto values = sequence(count);
        EXPECT_EQ(values, decode(toStream(compress(values)), count)) << count;
    }
}

// The input of a stream isn't necessarily aligned
TEST(FastPforDecode, UnalignedInput) {
    const auto values = sequence(1000);
    auto stream = toStream(compress(values));
    const auto length = stream.size();
    stream.insert(stream.begin(), 1, 0);
    stream.shrink_to_fit();
    EXPECT_EQ(values, decode(stream, values.size(), length, 1));
}

// The length comes from the tile; it can't be trusted to be within the data
TEST(FastPforDecode, ByteLengthBeyondData) {
    const auto values = sequence(1000);
    const auto stream = toStream(compress(values));
    EXPECT_THROW(decode(stream, values.size(), stream.size() + 64), std::runtime_error);
}

// Streams consist of whole 32-bit words
TEST(FastPforDecode, ByteLengthNotWordMultiple) {
    const auto values = sequence(1000);
    const auto stream = toStream(compress(values));
    EXPECT_THROW(decode(stream, values.size(), stream.size() - 1), std::runtime_error);
}

// The caller provides the buffer size, but the value count comes from the tile.
TEST(FastPforDecode, BufferSmallerThanDeclared) {
    const auto values = sequence(1000);
    const auto stream = toStream(compress(values));
    decoder::IntegerDecoder intDecoder;
    BufferStream bufferStream({stream.data(), stream.size()});
    std::vector<std::uint32_t> buffer(2);
    std::vector<std::uint32_t> result;
    EXPECT_THROW(intDecoder.decodeIntStream<std::uint32_t>(
                     bufferStream, buffer.data(), buffer.size(), result, makeMetadata(values.size(), stream.size())),
                 std::runtime_error);
}

// A variable-byte tail with more values than the tile declared must not be written past the output.
TEST(FastPforDecode, MoreValuesThanDeclared) {
    // Zero FastPFor values, followed by 1000 one-byte variable-byte values
    Words words = {0};
    words.resize(1 + 250, 0x81818181u);
    const auto stream = toStream(words);
    EXPECT_THROW(decode(stream, 3), std::runtime_error);
}

// The tile declares more values than the stream holds. The rest of the output would be left uninitialized.
TEST(FastPforDecode, FewerValuesThanDeclared) {
    const auto values = sequence(10);
    const auto stream = toStream(compress(values));
    EXPECT_THROW(decode(stream, 1000), std::runtime_error);

    const auto blocks = sequence(512);
    const auto blockStream = toStream(compress(blocks));
    EXPECT_THROW(decode(blockStream, 1000), std::runtime_error);
}

TEST(FastPforDecode, FastPforCountExceedsDeclared) {
    const auto values = sequence(1024);
    const auto stream = toStream(compress(values));
    EXPECT_THROW(decode(stream, 512), std::runtime_error);
}

TEST(FastPforDecode, EmptyStream) {
    EXPECT_THROW(decode({}, 10), std::runtime_error);
}

// The offset of the metadata section is read from the stream
TEST(FastPforDecode, MetadataOffsetOutOfRange) {
    const auto values = sequence(1000);
    const auto words = compress(values);
    for (const std::uint32_t offset : {0u, 1u, 0x7fffffffu, 0xffffffffu, static_cast<std::uint32_t>(words.size())}) {
        auto corrupt = words;
        corrupt[1] = offset;
        EXPECT_THROW(decode(toStream(corrupt), values.size()), std::runtime_error) << offset;
    }
}

// Cutting the stream short anywhere must be detected
TEST(FastPforDecode, Truncated) {
    const auto values = sequence(1000);
    const auto words = compress(values);
    for (std::size_t length = 0; length < words.size(); ++length) {
        const auto stream = toStream(Words(words.begin(), words.begin() + static_cast<std::ptrdiff_t>(length)));
        EXPECT_THROW(decode(stream, values.size()), std::runtime_error) << length;
    }
}

// Overwrite each word of a valid stream in turn. Whatever the result, nothing may be accessed out of bounds.
TEST(FastPforDecode, CorruptedWords) {
    for (const std::size_t count : {300ul, 1000ul}) {
        const auto values = sequence(count);
        const auto words = compress(values);
        for (std::size_t index = 0; index < words.size(); ++index) {
            for (const std::uint32_t replacement : {0u,
                                                    1u,
                                                    0x7fu,
                                                    0x80u,
                                                    0xffu,
                                                    0x8000u,
                                                    0xffffu,
                                                    0x7fffffffu,
                                                    0x80000000u,
                                                    0xfffffffeu,
                                                    0xffffffffu,
                                                    0x81818181u}) {
                auto corrupt = words;
                corrupt[index] = replacement;
                const auto stream = toStream(corrupt);
                try {
                    EXPECT_EQ(count, decode(stream, count).size());
                } catch (const std::runtime_error&) {
                    // expected for most corruptions
                }
            }
        }
    }
}

// --- The stream decoder

namespace {

std::vector<std::uint32_t> decodeWords(const Words& words, std::size_t count) {
    std::vector<std::uint32_t> out(count);
    decoder::fastpfor::decode(words, out);
    return out;
}

enum class Distribution {
    Zeros,
    Small,
    Outliers,
    Uniform,
    OneBitExceptions,
    MixedWidths
};

std::vector<std::uint32_t> distribution(Distribution kind, std::size_t count) {
    std::mt19937 rng(static_cast<unsigned>(count) + static_cast<unsigned>(kind));
    std::vector<std::uint32_t> values(count);
    for (auto& value : values) {
        switch (kind) {
            case Distribution::Zeros:
                value = 0;
                break;
            case Distribution::Small:
                value = rng() % 100;
                break;
            case Distribution::Outliers:
                value = (rng() % 16 == 0) ? rng() : rng() % 100;
                break;
            case Distribution::Uniform:
                value = rng();
                break;
            case Distribution::OneBitExceptions:
                // Most values fit in 7 bits, some need exactly one more, which is stored implicitly
                value = (rng() % 8 == 0) ? 128 + (rng() % 128) : rng() % 128;
                break;
            case Distribution::MixedWidths:
                value = rng() >> (rng() % 32);
                break;
        }
    }
    return values;
}

} // namespace

TEST(FastPforStream, RoundTrip) {
    // Around the block and page sizes, and with several pages
    for (const std::size_t count : {0ul,
                                    1ul,
                                    255ul,
                                    256ul,
                                    257ul,
                                    511ul,
                                    512ul,
                                    1000ul,
                                    65535ul,
                                    65536ul,
                                    65537ul,
                                    65536ul + 255ul,
                                    65536ul + 256ul,
                                    3 * 65536ul + 300ul}) {
        for (const auto kind : {Distribution::Zeros,
                                Distribution::Small,
                                Distribution::Outliers,
                                Distribution::Uniform,
                                Distribution::OneBitExceptions,
                                Distribution::MixedWidths}) {
            const auto values = distribution(kind, count);
            EXPECT_EQ(values, decodeWords(compress(values), count)) << count << " " << static_cast<int>(kind);
        }
    }
}

// Output buffers that start out with other contents must come out the same
TEST(FastPforStream, OutputFullyWritten) {
    const auto values = distribution(Distribution::Outliers, 1000);
    const auto words = compress(values);
    for (const std::uint32_t fill : {0u, 0xffffffffu, 0xa5a5a5a5u}) {
        std::vector<std::uint32_t> out(values.size(), fill);
        decoder::fastpfor::decode(words, out);
        EXPECT_EQ(values, out);
    }
}

TEST(FastPforStream, DecompressPartial) {
    // Less than one block, so there are no FastPFor blocks
    EXPECT_EQ((std::vector<std::uint32_t>{16, 17, 18}), decodeWords({0, 9605520}, 3));
}

namespace {

// Pack bytes into words, as they are in memory
Words packBytes(const std::vector<std::uint8_t>& bytes) {
    Words words((bytes.size() + 3) / 4);
    for (std::size_t i = 0; i < bytes.size(); ++i) {
        words[i / 4] |= std::uint32_t{bytes[i]} << (8 * (i % 4));
    }
    return words;
}

// A stream with one page of one block, assembled by hand so that any part of it can be wrong
Words onePageStream(const std::size_t packedWords,
                    const std::vector<std::uint8_t>& blockBytes,
                    const std::uint32_t bitmap,
                    const Words& exceptionLists,
                    const std::uint32_t metadataOffset = 0) {
    Words page;
    page.push_back(metadataOffset ? metadataOffset : static_cast<std::uint32_t>(1 + packedWords));
    page.resize(page.size() + packedWords, 0);
    page.push_back(static_cast<std::uint32_t>(blockBytes.size()));
    const auto bytes = packBytes(blockBytes);
    page.insert(page.end(), bytes.begin(), bytes.end());
    page.push_back(bitmap);
    page.insert(page.end(), exceptionLists.begin(), exceptionLists.end());

    Words stream = {256};
    stream.insert(stream.end(), page.begin(), page.end());
    return stream;
}

} // namespace

TEST(FastPforStream, HandBuiltPage) {
    // 3-bit values, all zero, except for exceptions at 5 and 7 which need 2 more bits: 3 and 1
    // The two exception values take 2 bits each, packed in a single word.
    const auto stream = onePageStream(24, {3, 2, 5, 5, 7}, /*bitmap=*/1u << 1, {2, 3 | (1 << 2)});
    std::vector<std::uint32_t> expected(256);
    expected[5] = 3 << 3;
    expected[7] = 1 << 3;
    EXPECT_EQ(expected, decodeWords(stream, 256));
}

TEST(FastPforStream, HandBuiltImpliedExceptionBit) {
    // An exception which needs one more bit than the block has no stored value: it is 1
    const auto stream = onePageStream(24, {3, 1, 4, 9}, /*bitmap=*/0, {});
    std::vector<std::uint32_t> expected(256);
    expected[9] = 1 << 3;
    EXPECT_EQ(expected, decodeWords(stream, 256));
}

TEST(FastPforStream, InvalidBlockFields) {
    // Each of these is otherwise a well-formed page
    EXPECT_THROW(decodeWords(onePageStream(8 * 33, {33, 0}, 0, {}), 256), std::runtime_error); // wider than 32 bits
    EXPECT_THROW(decodeWords(onePageStream(8 * 32, {255, 0}, 0, {}), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 1, 3, 0}, 0, {}), 256), std::runtime_error);  // no extra bits
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 1, 2, 0}, 0, {}), 256), std::runtime_error);  // fewer than the block
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 1, 33, 0}, 0, {}), 256), std::runtime_error); // wider than 32 bits
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 1, 0, 0}, 0, {}), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 1, 5, 0}, 0, {}), 256), std::runtime_error); // no stored value
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 2, 5, 0, 1}, 1u << 1, {1, 3}), 256), std::runtime_error); // 1 of 2
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 2, 5, 0}, 1u << 1, {2, 3}), 256),
                 std::runtime_error);                                                  // no positions
    EXPECT_THROW(decodeWords(onePageStream(24, {3}, 0, {}), 256), std::runtime_error); // no exception count
    EXPECT_THROW(decodeWords(onePageStream(24, {}, 0, {}), 256), std::runtime_error);  // no block info
}

TEST(FastPforStream, InvalidPageFields) {
    EXPECT_THROW(decodeWords(onePageStream(0, {0, 0}, 0, {}, /*metadataOffset=*/0xffffffffu), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 0}, 0, {}, /*metadataOffset=*/1000), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 0}, 0, {}, /*metadataOffset=*/10), 256), std::runtime_error);
    // Packed data which no block uses
    EXPECT_THROW(decodeWords(onePageStream(5, {0, 0}, 0, {}), 256), std::runtime_error);
    // Valid
    EXPECT_EQ(std::vector<std::uint32_t>(256), decodeWords(onePageStream(0, {0, 0}, 0, {}), 256));

    // The exception list sizes come from the page
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 0}, 1u << 1, {0xffffffffu}), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 0}, 1u << 1, {1000, 0}), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 0}, 1u << 1, {100}), 256), std::runtime_error);
    EXPECT_THROW(decodeWords(onePageStream(24, {3, 0}, 0x80000000u, {200}), 256), std::runtime_error);

    // The byte count of the block data
    auto stream = onePageStream(0, {0, 0}, 0, {});
    stream[2] = 0xffffffffu;
    EXPECT_THROW(decodeWords(stream, 256), std::runtime_error);
    stream[2] = 100;
    EXPECT_THROW(decodeWords(stream, 256), std::runtime_error);
}

TEST(FastPforStream, InvalidValueCount) {
    // Not a multiple of the block size
    Words words = {255, 1, 0, 0};
    EXPECT_THROW(decodeWords(words, 300), std::runtime_error);
    // More than the output
    EXPECT_THROW(decodeWords(onePageStream(0, {0, 0}, 0, {}), 255), std::runtime_error);
    // Less than the output, without anything to make up the difference
    EXPECT_THROW(decodeWords(onePageStream(0, {0, 0}, 0, {}), 300), std::runtime_error);
    EXPECT_THROW(decodeWords({}, 1), std::runtime_error);
    EXPECT_NO_THROW(decodeWords({}, 0));
}

TEST(FastPforStream, VariableByte) {
    // 1, 1, 1, ... as one byte values
    const Words ones = {0, 0x81818181u, 0x81818181u};
    EXPECT_EQ(std::vector<std::uint32_t>(8, 1), decodeWords(ones, 8));
    EXPECT_THROW(decodeWords(ones, 7), std::runtime_error); // more values than expected
    EXPECT_THROW(decodeWords(ones, 9), std::runtime_error); // fewer values than expected

    // Padding can follow the values
    EXPECT_EQ((std::vector<std::uint32_t>{1, 1}), decodeWords({0, 0x00008181u}, 2));

    // The largest value, and one too large
    EXPECT_EQ((std::vector<std::uint32_t>{0xffffffffu}), decodeWords({0, 0x7f7f7f7fu, 0x8f}, 1));
    EXPECT_THROW(decodeWords({0, 0x7f7f7f7fu, 0x90}, 1), std::runtime_error);
    // Six bytes
    EXPECT_THROW(decodeWords({0, 0x7f7f7f7fu, 0x8f7f}, 1), std::runtime_error);
    EXPECT_THROW(decodeWords({0, 0x7f7f7f7fu, 0x7f7f7f7fu, 0x7f7f7f7fu}, 1), std::runtime_error);
    // Never terminated
    EXPECT_THROW(decodeWords({0, 0x01010101u}, 1), std::runtime_error);
}

// Streams which don't fit the buffers must not write outside of them, wherever the limit is
TEST(FastPforStream, MutatedStreamsStayInBounds) {
    for (const auto kind : {Distribution::Outliers, Distribution::OneBitExceptions}) {
        const auto values = distribution(kind, 700);
        const auto words = compress(values);
        for (std::size_t index = 0; index < words.size(); ++index) {
            for (int bit = 0; bit < 32; ++bit) {
                auto corrupt = words;
                corrupt[index] ^= std::uint32_t{1} << bit;
                try {
                    EXPECT_EQ(values.size(), decodeWords(corrupt, values.size()).size());
                } catch (const std::runtime_error&) {
                }
            }
        }
    }
}
